// =============================================================================
// 3. DWARF CFI / ULEB128 / SLEB128 Decoders (Bộ giải mã biểu thức DWARF CFI)
// EN: Reconstructs the DWARF expression ULEB128/SLEB128 decoders referenced by
//     .rodata ('truncated uleb128 expression', 'CIE version is not 1 or 3').
// VI: Tái tạo bộ giải mã ULEB128/SLEB128 cho biểu thức DWARF trong .rodata.
// =============================================================================
std::uint64_t DecodeUleb128(const std::uint8_t* data, std::size_t len, std::size_t* consumed) noexcept {
    std::uint64_t result = 0ULL;
    unsigned shift = 0U;
    std::size_t i = 0U;
    while (i < len) {
        const std::uint8_t byte = data[i++];
        result |= static_cast<std::uint64_t>(byte & 0x7FU) << shift;
        if ((byte & 0x80U) == 0U) {
            if (consumed != nullptr) *consumed = i;
            return result;
        }
        shift += 7U;
        if (shift >= 64U) break;
    }
    if (consumed != nullptr) *consumed = i;
    return result;
}

std::int64_t DecodeSleb128(const std::uint8_t* data, std::size_t len, std::size_t* consumed) noexcept {
    std::int64_t result = 0LL;
    unsigned shift = 0U;
    std::size_t i = 0U;
    std::uint8_t byte = 0U;
    while (i < len) {
        byte = data[i++];
        result |= static_cast<std::int64_t>(byte & 0x7FU) << shift;
        shift += 7U;
        if ((byte & 0x80U) == 0U) break;
        if (shift >= 64U) break;
    }
    if ((shift < 64U) && ((byte & 0x40U) != 0U)) {
        result |= -(1LL << shift);
    }
    if (consumed != nullptr) *consumed = i;
    return result;
}

