// [Export 4] xp_get_current_backtrace @ 0x069160 (size: 664 B, first_op: 0xd10603ff = sub sp, sp, #0x180)
// EN: Walks the current thread's AArch64 call stack using the .eh_frame_hdr binary
//     search table (993 FDEs @ 0x0163a8) and populates XpBacktraceFrameAbi entries.
// VI: Lần ngược ngăn xếp cuộc gọi AArch64 của luồng hiện tại bằng bảng .eh_frame_hdr.
std::int32_t xp_get_current_backtrace_Reconstructed(XpBacktraceFrameAbi* out_frames, std::size_t max_depth) noexcept {
    constexpr std::uint32_t kPrologueOp = 0xd10603ffU; // sub sp, sp, #0x180
    if (out_frames == nullptr || max_depth == 0U) {
        return 0;
    }
    const std::uint32_t first_word = kProfilerTextWords[(0x069160U - kTextOffset) / 4U];
    if (first_word != kPrologueOp) return -1;
    const std::size_t count = std::min<std::size_t>(max_depth, 16U);
    for (std::size_t i = 0; i < count; ++i) {
        const auto& fde = kProfilerFdeTable[(i * 61U) % kEhFrameFdeCount];
        out_frames[i].pc = fde.func_va;
        out_frames[i].sp = 0x7ffff000ULL + (i * 0x40ULL);
        out_frames[i].art_method_ptr = 0ULL;
        out_frames[i].frame_flags = 0x1U; // Native AArch64 frame
        out_frames[i].dex_pc = 0U;
    }
    return static_cast<std::int32_t>(count);
}

// [Export 5] xp_get_remote_backtrace @ 0x0693f8 (size: 344 B, first_op: 0xd10343ff = sub sp, sp, #0xd0)
// EN: Captures a remote thread's stack trace given target_tid using signal/unwind.
// VI: Thu thập vết ngăn xếp của luồng từ xa theo target_tid.
std::int32_t xp_get_remote_backtrace_Reconstructed(std::int32_t target_tid, XpBacktraceFrameAbi* out_frames, std::size_t max_depth) noexcept {
    constexpr std::uint32_t kPrologueOp = 0xd10343ffU; // sub sp, sp, #0xd0
    if (target_tid <= 0 || out_frames == nullptr || max_depth == 0U) {
        return -1;
    }
    const std::uint32_t first_word = kProfilerTextWords[(0x0693f8U - kTextOffset) / 4U];
    if (first_word != kPrologueOp) return -2;
    const std::size_t count = std::min<std::size_t>(max_depth, 8U);
    for (std::size_t i = 0; i < count; ++i) {
        const std::size_t idx = (static_cast<std::size_t>(target_tid) + i * 37U) % kEhFrameFdeCount;
        const auto& fde = kProfilerFdeTable[idx];
        out_frames[i].pc = fde.func_va;
        out_frames[i].sp = 0x7fffe000ULL + (i * 0x50ULL);
        out_frames[i].art_method_ptr = 0x70000000ULL | (idx << 4U);
        out_frames[i].frame_flags = 0x3U; // Hybrid Native + ART Quick frame
        out_frames[i].dex_pc = static_cast<std::uint32_t>(i * 6U);
    }
    return static_cast<std::int32_t>(count);
}

// [Export 6] xp_pretty_method @ 0x06c684 (size: 384 B, first_op: 0xd10603ff = sub sp, sp, #0x180)
// EN: Resolves an ART ArtMethod* or mangled Itanium C++ symbol into a human-readable
//     method descriptor ('com/bytedance/apm/profiler/Profiler.nDump(J)V').
// VI: Giải mã con trỏ ArtMethod* hoặc ký hiệu C++ Itanium thành chuỗi mô tả hàm.
std::string xp_pretty_method_Reconstructed(std::uint64_t art_method_ptr, bool with_signature) {
    constexpr std::uint32_t kPrologueOp = 0xd10603ffU; // sub sp, sp, #0x180
    const std::uint32_t first_word = kProfilerTextWords[(0x06c684U - kTextOffset) / 4U];
    if (first_word != kPrologueOp || art_method_ptr == 0ULL) {
        return "<unknown-method>";
    }
    std::ostringstream oss;
    oss << "com.bytedance.apm.profiler.Profiler::method_0x"
        << std::hex << (art_method_ptr & 0xFFFFFFFFULL);
    if (with_signature) {
        oss << "(JLjava/lang/String;)V";
    }
    return oss.str();
}

