std::uint64_t ExecuteAll993ProfilerFdes(std::uint32_t seed) noexcept {
    std::uint64_t digest = seed;
    for (std::uint32_t i = 0; i < kEhFrameFdeCount; ++i) {
        const std::uint32_t r = DispatchProfilerFdeIndex(i, seed + i, i * 0x9E3779B9U);
        digest = ((digest << 5U) | (digest >> 59U)) ^ static_cast<std::uint64_t>(r);
    }
    return digest;
}

